{"description":"Diff sequences with difflib","cmd":"python3 - <<'PY'
import difflib
seqs={}
name=None
for line in open('sequences.fasta'):
    line=line.strip()
    if line.startswith('>'):
        name=line[1:]
        seqs[name]=''
    else:
        seqs[name]+=line
inp=seqs['input']; out=seqs['output']
sm=difflib.SequenceMatcher(None, inp, out, autojunk=False)
for tag,i1,i2,j1,j2 in sm.get_opcodes():
    if tag!='equal':
        print(tag, 'input',i1,i2,repr(inp[i1:i2]),'output',j1,j2,repr(out[j1:j2]),'dlen', (j2-j1)-(i2-i1))
print('total')
