{"description":"Compute Tms over candidate annealing lengths","cmd":"python3 - <<'PY'
import subprocess

seqs={}
name=None
for line in open('sequences.fasta'):
    line=line.strip()
    if line.startswith('>'):
        name=line[1:]
        seqs[name]=''
    else:
        seqs[name]+=line
inp=seqs['input']
# insertion point after index 212 (0-based), before 213
down = inp[213:]   # forward annealing starts here
up  = inp[0:213]   # upstream; reverse annealing is revcomp of the last Lr bases of up (ending at 212)
# Actually reverse annealing region: inp[213-Lr:213]
def rc(s):
    comp=str.maketrans('ACGT','TGCA')
    return s.translate(comp)[::-1]

def tm(seq):
    out=subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',seq],capture_output=True,text=True)
    return float(out.stdout.strip())

print('downstream start:', down[:60])
print('upstream end:', up[-60:])

print('\nForward candidates (anneal downstream):')
ftms={}
for L in range(15,46):
    s=down[:L]
    t=tm(s)
    ftms[L]=t
    print(L, s, round(t,2))

print('\nReverse candidates (revcomp of upstream):')
rtms={}
for L in range(15,46):
    s=rc(up[-L:])
    t=tm(s)
    rtms[L]=t
    print(L, s, round(t,2))
PY"}

{"description":"Enumerate valid primer length combos","cmd":"python3 - <<'PY'
import subprocess
seqs={}; name=None
for line in open('sequences.fasta'):
    line=line.strip()
    if line.startswith('>'):
        name=line[1:]; seqs[name]=''
    else:
        seqs[name]+=line
inp=seqs['input']
down=inp[213:]
def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]
def tm(seq):
    r=subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',seq],capture_output=True,text=True)
    return float(r.stdout.strip())
ft={L:tm(down[:L]) for L in range(15,46)}
rt={L:tm(rc(inp[213-L:213])) for L in range(15,46)}
valid=[]
for Lf in range(15,46):
    if not (58<=ft[Lf]<=72): continue
    for Lr in range(15,46):
        if not (58<=rt[Lr]<=72): continue
        if abs(ft[Lf]-rt[Lr])<=5:
            valid.append((Lf,Lr,round(ft[Lf],2),round(rt[Lr],2),round(abs(ft[Lf]-rt[Lr]),2)))
print(len(valid),'valid combos')
for v in valid:
    print(v)
PY"}

